import { Component, OnInit } from '@angular/core';
import { CommonModule } from '@angular/common';
import { Router } from '@angular/router';
import { HttpClient } from '@angular/common/http';
import { AuthService } from '../../core/services/auth.service';
import { AdminService } from '../../services/admin.service';
import { TranslationPipe } from '../../core/i18n/translation.pipe';
import { I18nService } from '../../core/i18n/i18n.service';

interface AdminUser {
  id: number;
  nome: string;
  email: string;
  tipo_usuario_id: number;
  criado_em: string;
}

interface AdminUsersResponse {
  success: boolean;
  data: AdminUser[];
  total: number;
}

@Component({
  selector: 'app-admin',
  standalone: true,
  imports: [CommonModule, TranslationPipe],
  templateUrl: './admin.component.html',
  styleUrls: ['./admin.component.scss']
})
export class AdminComponent implements OnInit {
  isAdmin$ = this.authService.isAdmin$;
  isLoading = true;
  hasError = false;
  errorMessage = '';
  usuarios: AdminUser[] = [];
  adminLogado = 0;
  acaoEmProgresso: { [key: string]: boolean } = {};

  constructor(
    private authService: AuthService,
    private adminService: AdminService,
    private router: Router,
    private http: HttpClient,
    private i18nService: I18nService
  ) {
    this.adminLogado = this.authService.getLoggedUserId();
  }

  ngOnInit(): void {
    this.isAdmin$.subscribe((isAdmin: boolean) => {
      if (!isAdmin) {
        this.router.navigate(['/dashboard']);
        return;
      }
      this.carregarUtilizadores();
    });
  }

  carregarUtilizadores(): void {
    this.isLoading = true;
    this.hasError = false;
    this.errorMessage = '';

    this.http.get<AdminUsersResponse>('http://localhost/gfp/backend/api/admin/utilizadores').subscribe({
      next: (response) => {
        this.usuarios = Array.isArray(response.data) ? response.data : [];
        this.isLoading = false;
      },
      error: (error) => {
        this.hasError = true;
        this.errorMessage = error?.error?.message || this.i18nService.translate('admin.loadError');
        this.isLoading = false;
      }
    });
  }

  formatarData(data: string): string {
    const date = new Date(data);
    return new Intl.DateTimeFormat('pt-BR', {
      dateStyle: 'medium',
      timeStyle: 'short'
    }).format(date);
  }

  getTipoUsuario(tipoUsuarioId: number): string {
    return tipoUsuarioId === 1
      ? this.i18nService.translate('admin.administrator')
      : this.i18nService.translate('admin.user');
  }

  alternarTipo(usuario: AdminUser): void {
    if (usuario.id === this.adminLogado) {
      return;
    }

    const chaveAcao = `alterar-tipo-${usuario.id}`;
    this.acaoEmProgresso[chaveAcao] = true;
    const novoTipo = usuario.tipo_usuario_id === 1 ? 2 : 1;

    this.adminService.atualizarTipoUsuario(usuario.id, novoTipo).subscribe({
      next: (response) => {
        if (response.success) {
          usuario.tipo_usuario_id = novoTipo;
        }
        this.acaoEmProgresso[chaveAcao] = false;
      },
      error: () => {
        this.acaoEmProgresso[chaveAcao] = false;
      }
    });
  }

  eliminarUtilizador(usuario: AdminUser): void {
    if (usuario.id === this.adminLogado) {
      return;
    }

    const confirmacao = confirm(`Tem a certeza que deseja eliminar o utilizador "${usuario.nome}"?`);
    if (!confirmacao) return;

    const chaveAcao = `eliminar-${usuario.id}`;
    this.acaoEmProgresso[chaveAcao] = true;

    this.adminService.eliminarUtilizador(usuario.id).subscribe({
      next: (response) => {
        if (response.success) {
          this.usuarios = this.usuarios.filter((u) => u.id !== usuario.id);
        }
        this.acaoEmProgresso[chaveAcao] = false;
      },
      error: () => {
        this.acaoEmProgresso[chaveAcao] = false;
      }
    });
  }
}
<div class="admin-container">
  <div *ngIf="isLoading" class="loading">
    <div class="spinner"></div>
  </div>

  <div *ngIf="!isLoading && (isAdmin$ | async)" class="admin-content">
    <div class="admin-header">
      <div>
        <h1>{{ 'admin.title' | t }}</h1>
        <p>{{ 'admin.subtitle' | t }}</p>
      </div>
      <button class="btn btn-primary" type="button" (click)="carregarUtilizadores()">{{ 'admin.refresh' | t }}</button>
    </div>

    <div *ngIf="hasError" class="alert-error">
      <strong>{{ 'transactions.error' | t }}:</strong> {{ errorMessage }}
    </div>

    <div *ngIf="!hasError" class="admin-body">
      <div class="admin-grid">
        <div class="admin-card">
          <h3>{{ 'admin.totalUsers' | t }}</h3>
          <p>{{ usuarios.length }}</p>
        </div>
      </div>

      <div *ngIf="usuarios.length > 0; else semUsuarios" class="user-table-wrapper">
        <table class="user-table">
          <thead>
            <tr>
              <th>{{ 'admin.id' | t }}</th>
              <th>{{ 'admin.name' | t }}</th>
              <th>{{ 'admin.email' | t }}</th>
              <th>{{ 'admin.type' | t }}</th>
              <th>{{ 'admin.createdAt' | t }}</th>
              <th>{{ 'admin.actions' | t }}</th>
            </tr>
          </thead>
          <tbody>
            <tr *ngFor="let usuario of usuarios">
              <td>{{ usuario.id }}</td>
              <td>{{ usuario.nome }}</td>
              <td>{{ usuario.email }}</td>
              <td>
                <span class="tipo-badge" [class.admin]="usuario.tipo_usuario_id === 1">
                  {{ getTipoUsuario(usuario.tipo_usuario_id) }}
                </span>
              </td>
              <td>{{ formatarData(usuario.criado_em) }}</td>
              <td class="actions-cell">
                <button 
                  class="btn-action btn-tipo"
                  [disabled]="acaoEmProgresso['alterar-tipo-' + usuario.id] || usuario.id === adminLogado"
                  (click)="alternarTipo(usuario)"
                  [title]="'admin.changeTypeTitle' | t">
                  {{ usuario.tipo_usuario_id === 1 ? ('admin.removeAdmin' | t) : ('admin.makeAdmin' | t) }}
                </button>
                <button 
                  class="btn-action btn-delete"
                  [disabled]="acaoEmProgresso['eliminar-' + usuario.id] || usuario.id === adminLogado"
                  (click)="eliminarUtilizador(usuario)"
                  [title]="'admin.deleteTitle' | t">
                  {{ 'admin.delete' | t }}
                </button>
              </td>
            </tr>
          </tbody>
        </table>
      </div>

      <ng-template #semUsuarios>
        <div class="empty-state">
          <p>{{ 'admin.noUsers' | t }}</p>
        </div>
      </ng-template>
    </div>
  </div>
</div>
